@@ -1,7 +1,18 @@
 import type { Provenance } from "./grade.ts";

-export const provenanceOf = (trailers: ReadonlyMap<string, string>): Provenance => {
-  const raw = trailers.get("Provenance");
-  if (raw === "authored" || raw === "inherited" || raw === "reconstructed") return raw;
-  return "unknown";
+export interface CommitIdentity {
+  authorEmail: string;
+  committerEmail: string;
+  isSigned: boolean;
+}
+
+export const provenanceOf = (identity: CommitIdentity): Provenance => {
+  // Only "authored" if the author and committer are the same person.
+  // This indicates direct authorship — not cherry-picked, rebased, or applied by someone else.
+  if (identity.authorEmail === identity.committerEmail) {
+    return "authored";
+  }
+
+  // If author ≠ committer, the commit was applied by someone else (cherry-picked, rebased, etc)
+  return "inherited";
 };
